import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 10;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ============================================================
// SCENE 1 — Hero title "Introducing Actors v3"
// ============================================================
const SCENE_ONE_DURATION = 70;

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 10, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");
  const subIn = springIn(frame, vfps, 32, "GENTLE");

  const driftY = ambientDrift(frame, 2.5, 110, "scene1-title");
  const driftEyebrow = ambientDrift(frame, 1.5, 140, "scene1-eyebrow");

  const HERO_LEAD = "Introducing";
  const HERO_HIGHLIGHT = "Actors v3";

  return (
    <AbsoluteFill style={{ fontFamily: BRAND.fonts.marketing }}>
      <Background />

      {/* Eyebrow — top-left anchored */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "18%",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0]) + driftEyebrow}px)`,
          fontFamily: BRAND.fonts.marketing,
          fontSize: 26,
          fontWeight: 600,
          color: COLORS.orange,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        Product Release · v3.0
      </div>

      {/* Hero block — off-center left, large */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "30%",
          maxWidth: "75%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: 132,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 1.02,
            display: "flex",
            flexWrap: "wrap",
            alignItems: "baseline",
            gap: 28,
          }}
        >
          <span
            style={{
              opacity: titleIn,
              transform: `translateY(${interpolate(titleIn, [0, 1], [40, 0])}px) scale(${interpolate(titleIn, [0, 1], [0.94, 1])})`,
              filter: `blur(${interpolate(titleIn, [0, 1], [8, 0])}px)`,
              display: "inline-block",
            }}
          >
            {HERO_LEAD}
          </span>
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `4px solid ${COLORS.orange}`,
              padding: "0 18px",
              borderRadius: 10,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
              display: "inline-block",
            }}
          >
            {HERO_HIGHLIGHT}
          </span>
        </div>

        {/* Subhead */}
        <div
          style={{
            marginTop: 44,
            fontFamily: BRAND.fonts.primary,
            fontSize: 36,
            fontWeight: 400,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.4,
            maxWidth: 820,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
          }}
        >
          The next generation of programmable cloud workers.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 2 — Three benefit lines
// ============================================================
const SCENE_TWO_DURATION = 95;

const BENEFITS = [
  { label: "Faster cold starts", descriptor: "Boot in milliseconds, not seconds" },
  { label: "Native MCP support", descriptor: "Connect any AI agent out of the box" },
  { label: "Pay per second", descriptor: "Billing that matches your actual usage" },
];

const CheckIcon: React.FC<{ size: number; progress: number }> = ({ size, progress }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <path
      d="M5 12.5 L10 17.5 L19 7"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={28}
      strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
    />
  </svg>
);

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 2, "GENTLE");
  const titleIn = springIn(frame, vfps, 6, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 16, "LIQUID");
  const cardIn = springIn(frame, vfps, 14, "LIQUID");

  const driftY = ambientDrift(frame, 2, 130, "scene2-title");
  const driftCard = ambientDrift(frame, 1.5, 160, "scene2-card");

  return (
    <AbsoluteFill style={{ fontFamily: BRAND.fonts.marketing }}>
      <Background />

      {/* Eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "13%",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
          fontFamily: BRAND.fonts.marketing,
          fontSize: 24,
          fontWeight: 600,
          color: COLORS.orange,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        What's new
      </div>

      {/* Headline — off-center left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "20%",
          maxWidth: "72%",
          transform: `translateY(${driftY}px)`,
          fontFamily: BRAND.fonts.marketing,
          fontWeight: 600,
          fontSize: 76,
          color: COLORS.text,
          letterSpacing: "-0.03em",
          lineHeight: 1.06,
          opacity: titleIn,
        }}
      >
        Built for the way you{" "}
        <span
          style={{
            background: COLORS.orangeTint,
            borderBottom: `3px solid ${COLORS.orange}`,
            padding: "0 12px",
            borderRadius: 8,
            display: "inline-block",
            clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
          }}
        >
          ship today
        </span>
      </div>

      {/* Benefits card */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          right: "8%",
          top: "44%",
          background: "rgba(255,255,255,0.04)",
          border: `1px solid ${COLORS.border}`,
          borderRadius: 20,
          padding: "44px 52px",
          display: "flex",
          flexDirection: "column",
          gap: 32,
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [28, 0]) + driftCard}px)`,
          boxShadow: "0 24px 64px rgba(0,0,0,0.35)",
        }}
      >
        {BENEFITS.map((item, i) => {
          const itemIn = staggeredSpring(
            frame,
            vfps,
            i,
            22,
            TIMING.staggerItem,
            "GENTLE"
          );
          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 28,
                opacity: itemIn,
                transform: `translateX(${interpolate(itemIn, [0, 1], [-30, 0])}px)`,
              }}
            >
              <CheckIcon size={44} progress={itemIn} />
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                }}
              >
                <div
                  style={{
                    fontFamily: BRAND.fonts.marketing,
                    fontWeight: 600,
                    fontSize: 44,
                    color: COLORS.text,
                    letterSpacing: "-0.015em",
                    lineHeight: 1.1,
                  }}
                >
                  {item.label}
                </div>
                <div
                  style={{
                    fontFamily: BRAND.fonts.primary,
                    fontWeight: 400,
                    fontSize: 26,
                    color: COLORS.textMuted,
                    lineHeight: 1.3,
                  }}
                >
                  {item.descriptor}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 3 — Sign-off "Build. Run. Scale."
// ============================================================
const SCENE_THREE_DURATION = 70;

const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const ctaIn = springIn(frame, vfps, 28, "ELASTIC");

  const driftY = ambientDrift(frame, 2, 100, "scene3-tag");
  const driftCta = ambientDrift(frame, 1.5, 140, "scene3-cta");

  const words = ["Build.", "Run.", "Scale."];

  return (
    <AbsoluteFill style={{ fontFamily: BRAND.fonts.marketing }}>
      <Background />

      {/* Eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "22%",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
          fontFamily: BRAND.fonts.marketing,
          fontSize: 26,
          fontWeight: 600,
          color: COLORS.orange,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        Actors v3 · Available now
      </div>

      {/* Tagline — three words stacked, staggered, off-center */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "32%",
          display: "flex",
          flexDirection: "column",
          gap: 4,
          transform: `translateY(${driftY}px)`,
        }}
      >
        {words.map((word, i) => {
          const wordIn = staggeredSpring(frame, vfps, i, 10, 12, "SNAPPY");
          const isLast = i === words.length - 1;
          return (
            <div
              key={i}
              style={{
                fontFamily: BRAND.fonts.marketing,
                fontWeight: 600,
                fontSize: 168,
                lineHeight: 1.0,
                letterSpacing: "-0.04em",
                color: isLast ? COLORS.text : COLORS.text,
                opacity: wordIn,
                transform: `translateY(${interpolate(wordIn, [0, 1], [50, 0])}px) scale(${interpolate(wordIn, [0, 1], [0.92, 1])})`,
                filter: `blur(${interpolate(wordIn, [0, 1], [10, 0])}px)`,
                display: "inline-block",
              }}
            >
              {isLast ? (
                <span
                  style={{
                    background: COLORS.orangeTint,
                    borderBottom: `5px solid ${COLORS.orange}`,
                    padding: "0 22px",
                    borderRadius: 12,
                    display: "inline-block",
                  }}
                >
                  {word}
                </span>
              ) : (
                word
              )}
            </div>
          );
        })}
      </div>

      {/* CTA pill — bottom-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          bottom: "14%",
          display: "flex",
          alignItems: "center",
          gap: 24,
          opacity: ctaIn,
          transform: `translateY(${interpolate(ctaIn, [0, 1], [18, 0]) + driftCta}px)`,
        }}
      >
        <div
          style={{
            border: `1.5px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: "16px 32px",
            fontFamily: BRAND.fonts.marketing,
            fontSize: 28,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "-0.005em",
          }}
        >
          Try Actors v3
        </div>
        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontSize: 24,
            fontWeight: 400,
            color: COLORS.textMuted,
          }}
        >
          apify.com/actors
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// Main composition
// ============================================================
export const durationInFrames =
  SCENE_ONE_DURATION + SCENE_TWO_DURATION + SCENE_THREE_DURATION - 2 * TRANSITION;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_ONE_DURATION + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={SCENE_TWO_DURATION + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={SCENE_THREE_DURATION}>
        <SceneThree />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
